import * as d3 from 'd3';
import { useMemo } from 'react';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from splom ----
type PenguinSpecies = 'Adelie' | 'Chinstrap' | 'Gentoo';
type PenguinDimension = 'culmenLength' | 'culmenDepth' | 'flipperLength' | 'bodyMass';
type Penguin = Record<PenguinDimension, number> & { species: PenguinSpecies };

const penguinSpecies: PenguinSpecies[] = ['Adelie', 'Chinstrap', 'Gentoo'];

const penguinDimensions: { key: PenguinDimension; label: string }[] = [
  { key: 'culmenLength', label: 'Culmen length' },
  { key: 'culmenDepth', label: 'Culmen depth' },
  { key: 'flipperLength', label: 'Flipper length' },
  { key: 'bodyMass', label: 'Body mass' }
];

type Group = {
  species: PenguinSpecies;
  count: number;
  stats: Record<PenguinDimension, [mean: number, sd: number]>;
};

/** Per-species means and standard deviations of the Palmer Station penguin measurements. */
const GROUPS: Group[] = [
  {
    species: 'Adelie',
    count: 45,
    stats: {
      culmenLength: [38.8, 2.66],
      culmenDepth: [18.3, 1.22],
      flipperLength: [190.0, 6.5],
      bodyMass: [3700, 459]
    }
  },
  {
    species: 'Chinstrap',
    count: 30,
    stats: {
      culmenLength: [48.8, 3.34],
      culmenDepth: [18.4, 1.14],
      flipperLength: [195.8, 7.1],
      bodyMass: [3733, 384]
    }
  },
  {
    species: 'Gentoo',
    count: 45,
    stats: {
      culmenLength: [47.5, 3.08],
      culmenDepth: [15.0, 0.98],
      flipperLength: [217.2, 6.5],
      bodyMass: [5076, 504]
    }
  }
];

// Seeded so the matrix is byte-identical across reloads.
const normal = d3.randomNormal.source(d3.randomLcg(0.42))(0, 1);

/** Weights on a bird's shared size factor; the rest is independent noise. Keeps unit variance. */
const SIZE_LOADING: Record<PenguinDimension, number> = {
  culmenLength: 0.5,
  culmenDepth: 0.45,
  flipperLength: 0.8,
  bodyMass: 0.8
};

function draw(stats: Group['stats'], key: PenguinDimension, size: number): number {
  const [mean, sd] = stats[key];
  const loading = SIZE_LOADING[key];
  return mean + sd * (loading * size + Math.sqrt(1 - loading * loading) * normal());
}

const penguins: Penguin[] = GROUPS.flatMap(({ species, count, stats }) =>
  d3.range(count).map(() => {
    const size = normal();
    return {
      species,
      culmenLength: Math.round(draw(stats, 'culmenLength', size) * 10) / 10,
      culmenDepth: Math.round(draw(stats, 'culmenDepth', size) * 10) / 10,
      flipperLength: Math.round(draw(stats, 'flipperLength', size)),
      bodyMass: Math.round(draw(stats, 'bodyMass', size) / 25) * 25
    };
  })
);

const MARGIN = { top: 26, right: 12, bottom: 34, left: 48 };
const PADDING = 22;
const RADIUS = 2.4;

const format = (v: number) => (Math.abs(v) >= 1000 ? d3.format('~s')(v) : String(v));

/** Interior ticks only, thinned to at most three, so neighbouring cells never share a label. */
function cellTicks(scale: d3.ScaleLinear<number, number>): number[] {
  const inner = scale.ticks(4).slice(1, -1);
  const stride = Math.max(1, Math.ceil(inner.length / 3));
  return inner.filter((_, i) => i % stride === 0);
}

/**
 * Rows to cross-plot, the numeric columns that become the matrix axes, and the
 * categories the points are coloured by.
 */
export type Data = {
  rows: Penguin[];
  dimensions: { key: PenguinDimension; label: string }[];
  species: string[];
};

const DEMO: Data = { rows: penguins, dimensions: penguinDimensions, species: penguinSpecies };

export default function Splom({ data = DEMO, width }: { data?: Data; width: number }) {
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const height = innerWidth + MARGIN.top + MARGIN.bottom;
  const dimensions = data.dimensions;
  const size = innerWidth / dimensions.length;

  // One horizontal scale per dimension, in cell-local coordinates, reused by every cell of that column.
  const xScales = useMemo(
    () =>
      dimensions.map((d) =>
        d3
          .scaleLinear()
          .domain(d3.extent(data.rows, (p) => p[d.key]) as [number, number])
          .nice()
          .range([PADDING / 2, size - PADDING / 2])
      ),
    [data, dimensions, size]
  );

  const yScales = useMemo(
    () => xScales.map((x) => x.copy().range([size - PADDING / 2, PADDING / 2])),
    [xScales, size]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(data.species).range(d3.schemeObservable10),
    [data]
  );

  const bottomTicks: Tick[][] = useMemo(
    () => xScales.map((x) => cellTicks(x).map((v) => ({ value: format(v), offset: x(v) - PADDING / 2 }))),
    [xScales]
  );

  const leftTicks: Tick[][] = useMemo(
    () => yScales.map((y) => cellTicks(y).map((v) => ({ value: format(v), offset: y(v) }))),
    [yScales]
  );

  const cells = useMemo(
    () => d3.cross(d3.range(dimensions.length), d3.range(dimensions.length)),
    [dimensions.length]
  );

  if (width === 0) return null;

  const matrix = size * dimensions.length;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Scatterplot matrix of four penguin body measurements, colored by species">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {data.species.map((species, i) => (
            <g key={species} transform={`translate(${i * 110},-10)`}>
              <circle r={4} fill={color(species)} />
              <text x={9} dy="0.32em" textAnchor="start">
                {species}
              </text>
            </g>
          ))}
        </g>

        {dimensions.map((d, j) => (
          <g key={d.key} transform={`translate(0,${j * size})`}>
            <AxisLeft ticks={leftTicks[j]} width={matrix} />
          </g>
        ))}

        {dimensions.map((d, i) => (
          <g key={d.key} transform={`translate(${i * size + PADDING / 2},0)`}>
            <AxisBottom
              ticks={bottomTicks[i]}
              height={matrix - PADDING / 2}
              width={size - PADDING}
            />
            <g className="axis">
              {bottomTicks[i].map(({ value, offset }) => (
                <line key={value} className="grid" x1={offset} x2={offset} y1={PADDING / 2} y2={matrix - PADDING / 2} />
              ))}
            </g>
          </g>
        ))}

        {cells.map(([i, j]) => (
          <g key={`${i}-${j}`} transform={`translate(${i * size},${j * size})`}>
            <rect
              x={PADDING / 2}
              y={PADDING / 2}
              width={size - PADDING}
              height={size - PADDING}
              fill="none"
              stroke="var(--line)"
            />
            {data.rows.map((p, k) => (
              <circle
                key={k}
                cx={xScales[i](p[dimensions[i].key])}
                cy={yScales[j](p[dimensions[j].key])}
                r={RADIUS}
                fill={color(p.species)}
                fillOpacity={0.7}
              />
            ))}
          </g>
        ))}

        <g fontSize={11} fontWeight={600} fill="var(--text)" pointerEvents="none">
          {dimensions.map((d, i) =>
            // ~6px per bold 11px character; drop the label rather than let it spill past its cell.
            d.label.length * 6 > size - PADDING * 1.5 ? null : (
              <text key={d.key} x={i * size + PADDING} y={i * size + PADDING} dy="0.71em">
                {d.label}
              </text>
            )
          )}
        </g>
      </g>
    </svg>
  );
}
